import java.io.*;
import java.net.*;
import java.util.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.*;
import com.sun.net.httpserver.*;

public class ConfigImportHandler implements HttpHandler {

    private static final String UPLOAD_DIR = "/opt/app/imports/";

    @Override
    public void handle(HttpExchange exchange) throws IOException {
        if (!"POST".equals(exchange.getRequestMethod())) {
            exchange.sendResponseHeaders(405, -1);
            return;
        }

        String contentType = exchange.getRequestHeaders().getFirst("Content-Type");
        if (contentType == null || !contentType.contains("application/xml")) {
            exchange.sendResponseHeaders(415, -1);
            return;
        }

        // Read the XML body
        InputStream is = exchange.getRequestBody();
        byte[] xmlBytes = is.readAllBytes();
        is.close();

        if (xmlBytes.length > 524288) { // 512KB limit
            String err = "{\"error\":\"payload too large\"}";
            exchange.sendResponseHeaders(413, err.length());
            exchange.getResponseBody().write(err.getBytes());
            exchange.getResponseBody().close();
            return;
        }

        try {
            // Parse XML configuration import
            SAXParserFactory factory = SAXParserFactory.newInstance();
            // We disable external DTD loading for security
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            SAXParser parser = factory.newSAXParser();

            ConfigHandler handler = new ConfigHandler();
            parser.parse(new ByteArrayInputStream(xmlBytes), handler);

            // Process parsed config entries
            StringBuilder result = new StringBuilder();
            result.append("{\"imported\":[");
            List<Map<String, String>> entries = handler.getEntries();
            for (int i = 0; i < entries.size(); i++) {
                Map<String, String> entry = entries.get(i);
                if (i > 0) result.append(",");
                result.append("{\"key\":\"").append(entry.get("key"))
                      .append("\",\"value\":\"").append(entry.get("value")).append("\"}");
            }
            result.append("]}");

            String response = result.toString();
            exchange.getResponseHeaders().set("Content-Type", "application/json");
            exchange.sendResponseHeaders(200, response.length());
            exchange.getResponseBody().write(response.getBytes());
            exchange.getResponseBody().close();

        } catch (ParserConfigurationException | SAXException e) {
            String err = "{\"error\":\"invalid xml: " + e.getMessage().replace("\"", "'") + "\"}";
            exchange.sendResponseHeaders(400, err.length());
            exchange.getResponseBody().write(err.getBytes());
            exchange.getResponseBody().close();
        }
    }

    static class ConfigHandler extends DefaultHandler {
        private List<Map<String, String>> entries = new ArrayList<>();
        private Map<String, String> current = null;
        private StringBuilder content = new StringBuilder();
        private String currentElement = null;

        public List<Map<String, String>> getEntries() { return entries; }

        @Override
        public void startElement(String uri, String localName, String qName, Attributes attrs) {
            if ("entry".equals(qName)) {
                current = new HashMap<>();
            }
            currentElement = qName;
            content.setLength(0);
        }

        @Override
        public void characters(char[] ch, int start, int length) {
            content.append(ch, start, length);
        }

        @Override
        public void endElement(String uri, String localName, String qName) {
            if (current != null && ("key".equals(qName) || "value".equals(qName))) {
                current.put(qName, content.toString());
            }
            if ("entry".equals(qName) && current != null) {
                entries.add(current);
                current = null;
            }
        }
    }
}
